using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using TextureFlow.UnityEditor;
public static class VoidSmoke {
 static int n;static void Check(bool ok,string text){if(!ok)throw new Exception(text);n++;Debug.Log("PASS "+text);}
 static void Reject(Action action,string text){bool stopped=false;try{action();}catch{stopped=true;}Check(stopped,text);}
 public static void Run(){try{AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string request=Directory.GetFiles("Assets/TextureFlow/Exports","void-request.json",SearchOption.AllDirectories).OrderByDescending(File.GetLastWriteTimeUtc).First(f=>{var config=JsonUtility.FromJson<VoidConfig>(File.ReadAllText(f));return config.areas.Length==1&&config.areas[0].name=="My space window";});VoidImporter.Import(request);string dir=Path.GetDirectoryName(request).Replace('\\','/');var material=AssetDatabase.LoadAssetAtPath<Material>(dir+"/Void.mat");Check(material!=null&&material.shader.name=="TextureFlow/Skybox Void","void material created");Check(!ShaderUtil.ShaderHasError(material.shader),"shader imports without errors");
 var quad=GameObject.CreatePrimitive(PrimitiveType.Quad);quad.name="Disposable void test";quad.transform.localScale=new Vector3(2,2,1);var renderer=quad.GetComponent<Renderer>();var original=new Material(Shader.Find("Unlit/Color"));original.color=Color.gray;AssetDatabase.CreateAsset(original,"Assets/Original.mat");renderer.sharedMaterials=new[]{original,original};EditorSceneManager.SaveScene(quad.scene,"Assets/VoidTest.unity");var target=FlowBridge.Snapshot().targets.First(t=>t.instanceId==renderer.GetInstanceID()&&t.slot==0);
 Func<FlowCommand> Command=()=>new FlowCommand{requestId=Guid.NewGuid().ToString("N"),sessionId=FlowBridge.Session,action="apply",target=target,materialPath=dir+"/Void.mat"};
 var bad=Command();bad.sessionId="stale";Reject(()=>VoidBridge.Execute(bad),"stale session refused");bad=Command();bad.expiresUtc=DateTime.UtcNow.AddMinutes(-1).ToString("O");Reject(()=>VoidBridge.Execute(bad),"expired request refused");bad=Command();bad.materialPath="Assets/Original.mat";Reject(()=>VoidBridge.Execute(bad),"outside export refused");bad=Command();bad.target=new FlowTarget{instanceId=target.instanceId,slot=0,globalId="wrong",materialGuid=target.materialGuid,materialInstanceId=target.materialInstanceId};Reject(()=>VoidBridge.Execute(bad),"wrong renderer identity refused");
 var command=Command();var reply=VoidBridge.Execute(command);Check(reply.success&&renderer.sharedMaterials[0]==material&&renderer.sharedMaterials[1]==original,"exact slot applied, other slot preserved");Check(File.Exists(reply.receiptPath),"restore record saved");Check(VoidBridge.Execute(command).success,"replay is idempotent");var restore=new FlowCommand{sessionId=FlowBridge.Session,action="restore",receiptPath=reply.receiptPath};Check(VoidBridge.Execute(restore).success&&renderer.sharedMaterials[0]==original,"old guarded restore supports void material");
 var changed=new Material(original);renderer.sharedMaterial=changed;Reject(()=>VoidBridge.Execute(Command()),"changed material refused");renderer.sharedMaterial=material;
 material=new Material(material);renderer.sharedMaterial=material;material.SetFloat("_AreaCount",8);for(int i=1;i<8;i++){material.SetTexture("_Sky"+i,Texture2D.whiteTexture);material.SetTexture("_Mask"+i,Texture2D.blackTexture);}material.SetVector("_Look0",new Vector4(0,4,.6f,1));material.SetVector("_Motion0",Vector4.zero);
 var cam=new GameObject("GPU camera").AddComponent<Camera>();cam.transform.position=new Vector3(0,0,-2);cam.orthographic=true;cam.orthographicSize=1;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.allowHDR=false;var rt=new RenderTexture(128,128,24);rt.Create();cam.targetTexture=rt;var read=new Texture2D(128,128,TextureFormat.RGB24,false);Func<Color[]> Render=()=>{cam.Render();RenderTexture.active=rt;read.ReadPixels(new Rect(0,0,128,128),0,0);read.Apply();RenderTexture.active=null;return read.GetPixels();};var a=Render();Check(!ShaderUtil.ShaderHasError(material.shader),"all eight shader areas compile on GPU");cam.transform.position=new Vector3(.5f,0,-2);cam.transform.LookAt(Vector3.zero);var b=Render();Check(a.Zip(b,(x,y)=>(x-y).maxColorComponent).Any(x=>x>.08f),"sky responds to camera movement on GPU");File.WriteAllBytes("void-gpu-preview.png",read.EncodeToPNG());
 cam.transform.position=new Vector3(0,0,-2);cam.transform.rotation=Quaternion.identity;material.SetVector("_Look0",new Vector4(1,4,.2f,1.5f));var starNear=Render();material.SetVector("_Look0",new Vector4(1,4,1.8f,1.5f));var starFar=Render();Check(starNear.Zip(starFar,(x,y)=>(x-y).maxColorComponent).Any(x=>x>.01f),"ready-made stars retain visible depth after GPU filtering");var pattern=new Texture2D(128,128,TextureFormat.RGBA32,false);for(int yy=0;yy<128;yy++)for(int xx=0;xx<128;xx++)pattern.SetPixel(xx,yy,new Color((Mathf.Sin(xx*.15f)+1)*.5f,(Mathf.Cos(yy*.2f)+1)*.5f,.3f));pattern.Apply();pattern.wrapMode=TextureWrapMode.Repeat;material.SetTexture("_Sky0",pattern);cam.transform.position=new Vector3(0,0,-2);cam.transform.rotation=Quaternion.identity;material.SetVector("_Look0",new Vector4(1,4,.2f,1.5f));a=Render();material.SetVector("_Look0",new Vector4(1,4,1.8f,1.5f));b=Render();Check(a.Zip(b,(x,y)=>(x-y).maxColorComponent).Any(x=>x>.05f),"depth changes GPU parallax");material.SetVector("_Look0",new Vector4(2,6,1.8f,1.5f));var c=Render();Check(b.Zip(c,(x,y)=>(x-y).maxColorComponent).Any(x=>x>.05f),"tunnel differs on GPU");Check(Mathf.Abs(a[0].r-b[0].r)<.01f&&Mathf.Abs(a[0].b-c[0].b)<.01f,"outside opening unaffected by depth settings");
 File.WriteAllText("void-unity-result.txt",n+" Unity checks passed. GPU: "+SystemInfo.graphicsDeviceName);EditorApplication.Exit(0);
 }catch(Exception ex){Debug.LogException(ex);File.WriteAllText("void-unity-result.txt",ex.ToString());EditorApplication.Exit(1);}}
}
